import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────────────
  // 1. BUILD GEOMETRY & MATERIAL
  // ─────────────────────────────────────────────────────────────────────────

  const geometry = new THREE.PlaneGeometry(0.8, 0.24); // capsule proportions

  // Load ceramic grain texture
  const material = new MeshBasicNodeMaterial({ color: 0xff2a38 });

  ctx.textureLoader.loadTexture('/prism-assets/chrome/ceramic-grain.map.png').then((tex) => {
    material.colorNode = mul(
      vec3(1.0, 0.16, 0.22), // accent red (#ff2a38)
      add(vec3(0.8), mul(tex, 0.2)) // subtle texture overlay
    );
    material.needsUpdate = true;
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.copy(config.scenePosition ?? new THREE.Vector3(0, 1.6, 0));
  if (config.rotation) plane.rotation.order = 'YXZ';
  if (config.scale) plane.scale.copy(config.scale);

  // ─────────────────────────────────────────────────────────────────────────
  // 2. EDGE LIGHT (rim accent for focus state)
  // ─────────────────────────────────────────────────────────────────────────

  const rimLight = new THREE.PointLight(0xff2a38, 0, 2.0);
  rimLight.position.set(0.5, 0.12, 0.3);
  rimLight.intensity = 0; // hidden by default
  plane.add(rimLight);

  // ─────────────────────────────────────────────────────────────────────────
  // 3. INTERACTION HANDLERS
  // ─────────────────────────────────────────────────────────────────────────

  let hoverTimeline = null;
  let pressTimeline = null;

  const handlers = {
    hover: (e) => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();

      // rise-in: y +0.15 → 0, power3.out, 0.7s
      hoverTimeline.to(plane.position, {
        y: plane.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      }, 0);

      // rim light fade in
      hoverTimeline.to(rimLight, {
        intensity: 1.2,
        duration: 0.5,
        ease: 'power2.out'
      }, 0);
    },
    unhover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.timeline();

      hoverTimeline.to(plane.position, {
        y: config.scenePosition?.y ?? 1.6,
        duration: 0.6,
        ease: 'power3.out'
      }, 0);

      hoverTimeline.to(rimLight, {
        intensity: 0,
        duration: 0.4
      }, 0);
    },
    click: () => {
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.timeline();

      // press-down: scale 0.97, 120ms, back.out
      pressTimeline.to(plane.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out'
      }, 0);

      pressTimeline.to(plane.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.3,
        ease: 'power4.out'
      }, 0.12);

      // emit navigate event
      ctx.emit('navigate', { to: 'hub-collection' });
    }
  };

  plane.userData.handlers = handlers;

  // ─────────────────────────────────────────────────────────────────────────
  // 4. CLEANUP
  // ─────────────────────────────────────────────────────────────────────────

  plane.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geometry.dispose();
    material.dispose();
  };

  return plane;
}
